183	 *
184	 * `spent` covers both of the core's ceilings, `iterations` and `runtime`, because
185	 * the decisions below turn on the same answer for either: the turn ended without
186	 * anybody choosing to end it, and nothing it planned will run. Which ceiling is a
187	 * sentence rather than a decision, so it stays on the word and is read by whatever
188	 * writes that sentence — see the result comment.
189	 *
190	 * `no-report` sits BELOW `handed-off` on purpose, and that placement is most of what
191	 * makes it usable. A run that ends by calling `create_pr`, `launch_sub_agent` or
192	 * `request_close_issue` gets no further turn — atoma's loop stops the moment the tool
193	 * returns — so "the last thing it said" is that tool call. Asked before the hand-off,
194	 * this would label every one of those as having reported nothing. Asked after, it is
195	 * left with exactly the runs where nothing continues AND nothing was said.
196	 */
197	export function endingOf(signals: TurnSignals): TurnEnding {
198	  const named = signals.directive.trim();
199	  const next = named === "" ? undefined : { agent: named };
200	
201	  if (!signals.succeeded || signals.endedBecause === "failed") return { ended: "failed" };
202	  if (signals.endedBecause === "loop") return { ended: "looped" };
203	  if (signals.endedBecause === "stopped") return { ended: "stopped" };
204	  if (signals.endedBecause === "iterations" || signals.endedBecause === "runtime") return { ended: "spent" };
205	  // A park beats the chain limits and every ordinary ending: the children it
206	  // started are already running, so the node is held no matter what the counters
207	  // say about the chain that launched them. The limits catch the re-invoked
208	  // parent instead.
209	  if (signals.parked) return { ended: "parked" };
210	  if (signals.loopLimitReached) return { ended: "chain-over", ...(next ? { next } : {}) };
211	  if (next || signals.chainContinues) return { ended: "handed-off", ...(next ? { next } : {}) };
212	  if (!signals.reported) return { ended: "no-report" };
213	  return { ended: "finished" };
214	}
